-- id 공식 계정(pinwith_id)·예시 계정·예시 리스트 4개. 먼저 seed_lang_loader.sql을 실행해 둘 것.
select private.seed_lang_examples('id', 'id', $doc${"official":{"display_name":"PinWith Resmi","bio":"Daftar tempat pilihan yang dibuat oleh tim PinWith."},"samples":[{"display_name":"Pengguna Contoh 1","bio":"Akun contoh buatan PinWith untuk menunjukkan cara teman-teman merencanakan trip bareng."},{"display_name":"Pengguna Contoh 2","bio":"Akun contoh buatan PinWith untuk menunjukkan cara teman-teman merencanakan trip bareng."},{"display_name":"Pengguna Contoh 3","bio":"Akun contoh buatan PinWith untuk menunjukkan cara teman-teman merencanakan trip bareng."}],"lists":[{"role":"plain","owner":"official","slug":"bali-ubud-sawah-dan-alam","kind":"course","title":"Sehari di Ubud: Sawah, Hutan Monyet & Jalan Kaki Santai","desc":"Rute klasik keliling Ubud dan sekitarnya: mulai pagi di jalur punggung bukit, lanjut ke hutan monyet, lalu terasering sawah paling ikonik di Bali. Cocok buat yang pertama kali ke Ubud.","themes":["Bali","Ubud","sawah","jalan kaki","alam"],"sections":[{"name":"Pagi: jalan kaki di Ubud","by":"official","items":[{"place_id":"ChIJ9XP0yms90i0Rn8QbqnT9E3w","title":"Bukit Campuhan","memo":"Datang sebelum jam 8 pagi supaya belum panas dan masih sepi. Jalurnya terbuka tanpa peneduh, jadi bawa topi dan air minum.","tags":["sunrise","trekking"],"lat":-8.503581,"lng":115.254758},{"place_id":"ChIJi8jNFwY90i0RHk2xN6jZmik","title":"Sawah Penestanan","memo":"Jalur setapak di antara sawah dengan warung dan kafe kecil di sepanjang jalan. Enak buat sarapan sambil lihat petani bekerja.","tags":["sawah","santai"],"lat":-8.494939,"lng":115.247504},{"place_id":"ChIJ8ajmy0A90i0RyTmTz7x6GEE","title":"Sawah Kajeng","memo":"Masuk lewat Jalan Kajeng dari pusat Ubud, cuma beberapa menit jalan kaki. Alternatif sawah yang dekat kalau tidak sempat ke Tegallalang.","tags":["dekat pusat","gratis"],"lat":-8.500623,"lng":115.261832}]},{"name":"Siang: hutan & budaya","by":"official","items":[{"place_id":"ChIJZ5sY9kM90i0RVsPvSxZD7LY","title":"Monkey Forest Ubud","memo":"Simpan kacamata, topi, dan makanan di dalam tas tertutup karena monyet suka merebut barang. Jangan menatap mata monyet terlalu lama.","tags":["ikonik","hati-hati monyet"],"lat":-8.519373,"lng":115.26063}]},{"name":"Sore: terasering utara Ubud","by":"official","items":[{"place_id":"ChIJ4wD5Iwsi0i0R7QRsOGmJGo0","title":"Tegallalang","memo":"Siang hari sangat ramai tur; datang sore atau pagi sekali untuk suasana lebih tenang. Siapkan uang kecil untuk donasi di beberapa titik jalur.","tags":["ikonik","foto"],"lat":-8.431711,"lng":115.279303},{"place_id":"ChIJf0hObjEj0i0RbeqTyPAXiQc","title":"Mupu Rice Terrace","memo":"Masih satu kawasan dengan Tegallalang tapi jauh lebih sepi. Cocok buat yang mau menikmati terasering tanpa desak-desakan.","tags":["tersembunyi","tenang"],"lat":-8.429997,"lng":115.279453},{"place_id":"ChIJy1lVfVQZ0i0RJ712N5AVRGA","title":"Sawah Mancingan","memo":"Ada di arah Tampaksiring, bisa digabung dengan kunjungan ke pura di sekitarnya. Pemandangan lembahnya bagus saat matahari mulai turun.","tags":["sunset","lembah"],"lat":-8.422935,"lng":115.31703},{"place_id":"ChIJ-9cMAqsn0i0RmoPm81-HDy8","title":"Jatiluwih","memo":"Warisan Dunia UNESCO di Tabanan, sekitar 1,5 jam berkendara dari Ubud. Lebih cocok dijadikan setengah hari tersendiri dan udaranya lebih sejuk.","tags":["UNESCO","day trip"],"lat":-8.370094,"lng":115.131227}]}],"comments":[]},{"role":"creator","owner":"official","slug":"vlog-jogja-borobudur-prambanan","kind":"course","title":"[Vlog] 2 Hari di Jogja: Sunrise Borobudur sampai Senja di Candi Ijo","desc":"Rute yang aku pakai buat vlog Jogja: kejar sunrise di Punthuk Setumbu, keliling Borobudur, lanjut Prambanan, tutup dengan senja di Candi Ijo. Hari kedua santai di kota. Lengkap dengan tips ambil gambar!","themes":["Vlog","Jogja","candi","sunrise","konten"],"sections":[{"name":"Hari 1: candi dari subuh sampai senja","by":"official","items":[{"place_id":"ChIJkdTMoQWNei4Rsc0SXjG2F2c","title":"Punthuk Setumbu","memo":"Di video menit 0:45 itu Borobudur muncul dari kabut! Berangkat dari kota sekitar jam 3 subuh, bawa jaket, dan pakai lensa tele kalau ada.","tags":["sunrise","drone view"],"lat":-7.609376,"lng":110.177792},{"place_id":"ChIJl9anCfCMei4Ry8NNdDRD0w0","title":"Candi Borobudur","memo":"Akses naik ke struktur candi sekarang dibatasi dan pakai tiket khusus, jadi cek dan pesan online jauh-jauh hari. Ambil shot stupa dari pelataran pagi hari sebelum terik.","tags":["UNESCO","wajib"],"lat":-7.607874,"lng":110.203751},{"place_id":"ChIJ0VnY2-Naei4RLVqVJTug5xk","title":"Candi Prambanan","memo":"Golden hour di sini juara: ambil wide shot dari halaman rumput supaya tiga candi utama masuk satu frame. Drone butuh izin, jangan diterbangkan sembarangan.","tags":["golden hour","UNESCO"],"lat":-7.752021,"lng":110.491467},{"place_id":"ChIJpXpAMhJbei4R66paHGNQXGQ","title":"Candi Ijo","memo":"Candi tertinggi di Jogja dengan view kota dan landasan bandara lama dari atas bukit. Spot senja favoritku, tapi jalannya menanjak jadi pastikan kendaraan fit.","tags":["sunset","hidden gem"],"lat":-7.783845,"lng":110.511984}]},{"name":"Hari 2: santai di kota","by":"official","items":[{"place_id":"ChIJK8_C0JNXei4RE74coPghaic","title":"Taman Sari","memo":"Sumur Gumuling paling fotogenik pagi hari saat cahaya masuk dari atas tangga. Datang awal biar tidak antre giliran foto.","tags":["sejarah","spot foto"],"lat":-7.810055,"lng":110.359301},{"place_id":"ChIJl5MfmllXei4RD-EMKO4ov-s","title":"Titik Nol Kilometer","memo":"Bagus buat timelapse malam dengan lampu-lampu gedung kolonial. Pasang tripod di trotoar sisi pinggir supaya tidak menghalangi orang.","tags":["malam","timelapse"],"lat":-7.801397,"lng":110.364764},{"place_id":"ChIJX7qtm6BZei4R14JMFuKTNxQ","title":"Malioboro","memo":"Ambil B-roll suasana jalanan dan andong menjelang malam. Untuk oleh-oleh, bandingkan harga dulu di beberapa toko sebelum beli.","tags":["street","oleh-oleh"],"lat":-7.792639,"lng":110.365861}]}],"comments":[]},{"role":"friends","owner":"ex1","slug":"seoul-4-hari-bertiga","kind":"collection","title":"Seoul 4 Hari Bertiga","desc":"Rencana trip ke Seoul bareng tiga sahabat. Masing-masing menambahkan tempat incarannya, lalu kita diskusi di komentar. Rencana final ada di komentar tempat Namsan Seoul Tower!","themes":["Seoul","Korea","trip bareng","musim gugur"],"sections":[{"name":"Pilihan Contoh 1: istana & hanok","by":"ex1","items":[{"place_id":"ChIJod7tSseifDUR9hXHLFNGMIs","title":"Gyeongbokgung","memo":"Kalau sewa dan pakai hanbok, masuk istananya gratis. Ada upacara pergantian penjaga beberapa kali sehari di gerbang depan.","tags":["hanbok","istana"],"lat":37.579617,"lng":126.977041},{"place_id":"ChIJT8H4r9qifDURmuXJ_6m6vM0","title":"Bukchon Hanok Village","memo":"Ini kawasan pemukiman, jadi jangan berisik dan perhatikan jam kunjungan yang dibatasi untuk turis.","tags":["hanok","foto"],"lat":37.58147,"lng":126.984952},{"place_id":"ChIJ4wh0zluifDURaFBW2pdrKf8","title":"Changdeokgung","memo":"Taman rahasianya (Huwon) hanya bisa dimasuki dengan tur terjadwal, pesan tiketnya lebih awal.","tags":["UNESCO","taman"],"lat":37.579431,"lng":126.991043},{"place_id":"ChIJe4Jbot2ifDUR2zWhruwyaow","title":"Ikseon-dong","memo":"Gang hanok penuh kafe dan toko lucu, enak buat ngopi setelah dari istana.","tags":["kafe","gang"],"lat":37.573713,"lng":126.990127}]},{"name":"Pilihan Contoh 2: belanja & jajan","by":"ex2","items":[{"place_id":"ChIJqb-ne_CifDURR-yH8a3sjXM","title":"Myeongdong","memo":"Surga skincare dan jajanan kaki lima di malam hari. Banyak toko kasih sampel dan diskon turis kalau tunjukkan paspor.","tags":["skincare","jajan"],"lat":37.561669,"lng":126.985844},{"place_id":"ChIJfYjlFvWifDURYSDsoxYbN80","title":"Pasar Namdaemun","memo":"Pasar tradisional terbesar, bagus buat oleh-oleh murah. Siap-siap menawar sedikit.","tags":["oleh-oleh","pasar"],"lat":37.559277,"lng":126.977703},{"place_id":"ChIJm3V0fu2ifDURRJ8IMUijVtY","title":"Pasar Gwangjang","memo":"Banyak jajanan yang mengandung babi, jadi tanyakan bahannya dulu dan pilih yang berbahan sayur atau seafood.","tags":["street food","cek bahan"],"lat":37.570039,"lng":126.999604},{"place_id":"ChIJ8xRYr29FezUR3AtFqx2pIlw","title":"DDP","memo":"Bangunan futuristis karya Zaha Hadid, cantik dengan lampu malam. Di sekitarnya banyak mal grosir fashion yang buka sampai larut.","tags":["arsitektur","malam"],"lat":37.566526,"lng":127.009224}]},{"name":"Pilihan Contoh 3: view & anak muda","by":"ex3","items":[{"place_id":"ChIJqWqOqFeifDURpYJ5LnxX-Fw","title":"Namsan Seoul Tower","memo":"Naik kereta gantung atau jalan kaki lewat jalur taman. View malamnya paling cantik.","tags":["view","malam"],"lat":37.551169,"lng":126.988227},{"place_id":"ChIJ68AiKsWYfDUROpTctLKtxtU","title":"Hongdae","memo":"Busking dan dance cover K-pop di jalanan tiap malam akhir pekan. Banyak toko baju murah juga.","tags":["K-pop","busking"],"lat":37.556197,"lng":126.925034},{"place_id":"ChIJIwCT4-yifDUR1E63iG76hr0","title":"Cheonggyecheon","memo":"Sungai di tengah kota yang enak buat jalan santai malam hari, gratis dan dekat Myeongdong.","tags":["jalan santai","gratis"],"lat":37.569102,"lng":126.978669},{"place_id":"ChIJj1q-SjCjfDURrEOH3_cjrMM","title":"Naksan Park","memo":"Jalan menyusuri tembok kota kuno dengan view lampu kota saat senja. Pakai sepatu nyaman karena menanjak.","tags":["sunset","tembok kota"],"lat":37.576079,"lng":127.008988}]}],"comments":[{"place_id":"ChIJod7tSseifDUR9hXHLFNGMIs","by":"ex1","body":"Hari pertama ke Gyeongbokgung pakai hanbok yuk? Sewa di dekat stasiun, terus lanjut jalan kaki ke Bukchon.","replies":[{"by":"ex2","body":"Setuju! Tapi istananya tutup satu hari dalam seminggu, cek dulu biar nggak salah hari."},{"by":"ex3","body":"Sewa hanbok yang ada pilihan hijab-friendly juga ya, biar fotonya tetap nyaman."}]},{"place_id":"ChIJm3V0fu2ifDURRJ8IMUijVtY","by":"ex2","body":"Gwangjang wajib, tapi kita cari yang aman ya. Nanti aku cari kios yang jelas pakai seafood atau sayur.","replies":[{"by":"ex1","body":"Oke, kalau ragu kita makan di restoran halal di Itaewon aja malamnya. Naik subway cuma sebentar."}]},{"place_id":"ChIJ68AiKsWYfDUROpTctLKtxtU","by":"ex3","body":"Hongdae paling seru malam Sabtu, banyak busking. Bisa kita taruh di hari ketiga?","replies":[{"by":"ex2","body":"Bisa. Siangnya kita ke Myeongdong dulu belanja skincare, sore baru geser ke Hongdae."},{"by":"ex1","body":"Budget belanja dibatasi ya, koper kita kecil semua wkwk."}]},{"place_id":"ChIJj1q-SjCjfDURrEOH3_cjrMM","by":"ex3","body":"Naksan pas senja cakep banget, tapi jalannya nanjak. Gimana kalau gabung sama Ikseon-dong di hari pertama?","replies":[{"by":"ex1","body":"Hari pertama sudah capek dari istana. Mending hari kedua sesudah DDP, lokasinya juga nggak jauh."}]},{"place_id":"ChIJqWqOqFeifDURpYJ5LnxX-Fw","by":"ex1","body":"Oke, ini rencana final kita ya! Hari 1: Gyeongbokgung (hanbok), Bukchon, Changdeokgung, Ikseon-dong. Hari 2: Namdaemun, Gwangjang, DDP, senja di Naksan. Hari 3: Myeongdong, Cheonggyecheon, malam di Hongdae. Hari 4: santai pagi lalu Namsan Tower sebelum ke bandara.","replies":[{"by":"ex2","body":"Mantap! Hari 4 bawa koper dititip di loker stasiun aja biar nggak repot."},{"by":"ex3","body":"Sip. Kalau hujan, Namsan kita tukar ke malam hari ketiga. Pakai T-money biar gampang naik subway."}]}]},{"role":"food","owner":"official","slug":"jakarta-kuliner-legendaris","kind":"collection","title":"Kuliner Legendaris Jakarta","desc":"Dari nasi goreng kambing pinggir jalan sampai rumah makan bergaya kolonial: tempat makan di Jakarta yang sudah lama jadi langganan dan cocok buat ajak tamu dari luar kota.","themes":["Jakarta","kuliner","legendaris","masakan Indonesia"],"sections":[{"name":"Kaki lima & rumah makan sederhana","by":"official","items":[{"place_id":"ChIJfRMs_in0aS4R2b7SZJn_YL0","title":"Nasi Goreng Kambing Kebon Sirih","memo":"Nasi goreng kambing berempah yang terkenal sejak lama, buka dari sore sampai malam. Datang lebih awal karena antreannya bisa panjang.","tags":["kaki lima","malam"],"lat":-6.183193,"lng":106.825714},{"place_id":"ChIJJz2UecP1aS4RTeIAJ4rH0v0","title":"Medan Baru","memo":"Rumah makan Tionghoa-Medan di kawasan Pasar Baru; cocok untuk makan bareng keluarga besar, pesan beberapa lauk untuk dibagi.","tags":["Medan","keluarga"],"lat":-6.158877,"lng":106.831575}]},{"name":"Masakan rumahan Nusantara","by":"official","items":[{"place_id":"ChIJLSH8Jz_0aS4RyizVJgakXk4","title":"Dua Nyonya Cikini","memo":"Masakan rumahan Betawi dan peranakan dengan suasana rumah lama yang nyaman. Pas untuk sarapan atau makan siang setelah jalan-jalan di Cikini.","tags":["peranakan","sarapan"],"lat":-6.187897,"lng":106.836922},{"place_id":"ChIJmeD-E9T1aS4REAKDnkrtxXY","title":"Remboelan Grand Indonesia","memo":"Pilihan praktis di mal pusat kota dengan menu khas Nusantara. Saat jam makan siang kerja biasanya ramai, datang sebelum jam 12.","tags":["mal","praktis"],"lat":-6.19499,"lng":106.821093},{"place_id":"ChIJR2I0yCX0aS4RnsVGtM67WiI","title":"Seribu Rasa Menteng","memo":"Perpaduan masakan Indonesia dan Asia Tenggara dengan banyak menu seafood. Reservasi untuk makan malam rombongan.","tags":["seafood","rombongan"],"lat":-6.195489,"lng":106.824794}]},{"name":"Suasana klasik untuk acara spesial","by":"official","items":[{"place_id":"ChIJadVPFf8dai4RRM83ZusjgqM","title":"Café Batavia","memo":"Gedung kolonial di Kota Tua yang menghadap Taman Fatahillah. Mampir untuk istirahat dan minum setelah keliling museum di sekitarnya.","tags":["Kota Tua","kolonial"],"lat":-6.134368,"lng":106.812735},{"place_id":"ChIJ7eBosjv0aS4RfpIv1feiios","title":"Tugu Kunstkring Paleis","memo":"Bekas gedung seni zaman Belanda di Menteng dengan interior megah. Reservasi dulu, terutama untuk akhir pekan.","tags":["bersejarah","reservasi"],"lat":-6.188895,"lng":106.833455},{"place_id":"ChIJZ3XYYj70aS4RyDFzTQx4BFY","title":"Lara Djonggrang","memo":"Interior bernuansa candi dan barang antik, cocok untuk menjamu tamu dari luar negeri. Wajib reservasi lebih dulu.","tags":["antik","makan malam"],"lat":-6.194136,"lng":106.836232},{"place_id":"ChIJ91EGWSP0aS4R2FsHVktCgwk","title":"Plataran Menteng","memo":"Masakan Indonesia dengan penyajian modern di rumah tua yang asri. Bagus untuk makan malam keluarga atau perayaan kecil.","tags":["perayaan","modern"],"lat":-6.191901,"lng":106.828581}]}],"comments":[]}]}$doc$::jsonb);
